-- Run after supabase-planning.sql. Retains legacy rules and audit history.
begin;
create table if not exists public.ao_plan_prices (
 id uuid primary key, name text not null, effective_date date not null,
 status text not null default 'draft' check(status in ('draft','published')), payload jsonb not null,
 published_data jsonb, published_at timestamptz, revision integer not null default 1,
 updated_by text not null, updated_at timestamptz not null default now()
);
create table if not exists public.ao_plan_commissions (like public.ao_plan_prices including all);
alter table public.ao_plan_budgets add column if not exists published_data jsonb;
alter table public.ao_plan_budgets add column if not exists published_at timestamptz;
alter table public.ao_plan_budgets add column if not exists rules_snapshot jsonb;
alter table public.ao_plan_budgets alter column rule_id drop not null;
update public.ao_plan_budgets b set rules_snapshot=r.payload from public.ao_plan_rules r where b.rule_id=r.id and b.rules_snapshot is null;
update public.ao_plan_budgets b set published_data=jsonb_build_object('name',name,'entity_id',entity_id,'year',year,'payload',payload,'rules_snapshot',rules_snapshot),published_at=updated_at where status='published' and published_data is null;
update public.ao_plan_entities set name='Physical Centre',kind='branch',revision=revision+1,updated_at=now() where id='c0000000-0000-4000-8000-000000000002' and name='AHCI';
alter table public.ao_plan_prices enable row level security;
alter table public.ao_plan_commissions enable row level security;
revoke all on public.ao_plan_prices,public.ao_plan_commissions from public,anon,authenticated;
grant select on public.ao_plan_prices,public.ao_plan_commissions to service_role;
create or replace function public.ao_planning_save(p_kind text,p_id uuid,p_revision integer,p_actor text,p_data jsonb)
returns jsonb language plpgsql security definer set search_path='' as $$
declare tab text; oldrow jsonb; result jsonb; rid uuid; publication jsonb;
begin
 tab:=case p_kind when 'prices' then 'ao_plan_prices' when 'commissions' then 'ao_plan_commissions' when 'budget' then 'ao_plan_budgets' end;
 if tab is null then raise exception 'Invalid planning record'; end if;
 if p_kind<>'budget' and p_id is distinct from 'c0000000-0000-4000-8000-000000000003'::uuid then raise exception 'Use current settings'; end if;
 if p_id is not null then
  execute format('select to_jsonb(t) from public.%I t where id=$1 for update',tab) into oldrow using p_id;
  if oldrow is null or (oldrow->>'revision')::integer<>p_revision then raise exception 'PLANNING_CONFLICT'; end if;
 end if;
 rid:=coalesce(p_id,gen_random_uuid());
 publication:=case when p_data->>'status'='published' then p_data-'status' else oldrow->'published_data' end;
 if p_kind='budget' then
  if oldrow is not null and oldrow->>'entity_id'<>p_data->>'entity_id' then raise exception 'Budget entity cannot change'; end if;
  insert into public.ao_plan_budgets(id,entity_id,name,year,status,payload,rules_snapshot,published_data,published_at,updated_by)
  values(rid,(p_data->>'entity_id')::uuid,p_data->>'name',(p_data->>'year')::integer,p_data->>'status',p_data->'payload',p_data->'rules_snapshot',publication,case when p_data->>'status'='published' then now() else null end,p_actor)
  on conflict(id) do update set name=excluded.name,year=excluded.year,status=excluded.status,payload=excluded.payload,rules_snapshot=excluded.rules_snapshot,published_data=excluded.published_data,published_at=case when excluded.status='published' then now() else public.ao_plan_budgets.published_at end,revision=public.ao_plan_budgets.revision+1,updated_by=p_actor,updated_at=now();
 else
  execute format('update public.%I set name=$2,effective_date=$3,status=$4,payload=$5,published_data=$6,published_at=case when $4=''published'' then now() else published_at end,revision=revision+1,updated_by=$7,updated_at=now() where id=$1',tab)
  using rid,p_data->>'name',(p_data->>'effective_date')::date,p_data->>'status',p_data->'payload',publication,p_actor;
 end if;
 execute format('select to_jsonb(t) from public.%I t where id=$1',tab) into result using rid;
 insert into public.ao_plan_audit(kind,record_id,actor,before_data,after_data) values(p_kind,rid,p_actor,oldrow,result);
 return result;
end; $$;
revoke all on function public.ao_planning_save(text,uuid,integer,text,jsonb) from public,anon,authenticated;
grant execute on function public.ao_planning_save(text,uuid,integer,text,jsonb) to service_role;
